+std::vector<Visit> LastVisits(const std::vector<Visit>& visits, int n) {
+    if (n <= 0) {
+        return {};
+    }
+
+    std::vector<Visit> tail;
+    tail.reserve(n);
+
+    for (size_t i = visits.size() - n; i < visits.size(); ++i) {
+        tail.push_back(visits[i]);
+    }
+
+    return tail;
 }

 bool ByTime(const Visit& a, const Visit& b) {
     return a.at < b.at;
 }

